        let s = args[1].parse().unwrap_or(0);
        println!("Using seed {} from command line", s);
        s
    } else {
        let s = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        println!("Using seed {}", s);
        s
