}

fn right_depth(node: &Rc<RefCell<BOSNode>>) -> u32 {
    node.borrow().right_child_node.as_ref()
        .map_or(0, |n| n.borrow().depth + 1)
}

fn update_depth(node: &Rc<RefCell<BOSNode>>) {
    let l = left_depth(node);
    let r = right_depth(node);
    node.borrow_mut().depth = std::cmp::max(l, r);
}

fn balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    right_depth(node) as i32 - left_depth(node) as i32
