fn update_child_counts(node: &Rc<RefCell<BOSNode>>) {
    let left_count = node.borrow().left_child_node.as_ref()
        .map_or(0, |n| n.borrow().left_child_count + n.borrow().right_child_count + 1);
    let right_count = node.borrow().right_child_node.as_ref()
        .map_or(0, |n| n.borrow().left_child_count + n.borrow().right_child_count + 1);
