fn rotate_right(tree: &mut BOSTree, node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // node is the node to rotate right around
    let left = node.borrow_mut().left_child_node.take().unwrap(); // must have left child
    let left_right = left.borrow_mut().right_child_node.take();

    // Update parent links
    let parent_weak = node.borrow().parent_node.clone();
    left.borrow_mut().parent_node = parent_weak;
    node.borrow_mut().parent_node = Some(Rc::downgrade(&left));

    if let Some(lr) = left_right {
        lr.borrow_mut().parent_node = Some(Rc::downgrade(node));
        node.borrow_mut().left_child_node = Some(lr);
    } else {
        node.borrow_mut().left_child_node = None;
    }

    left.borrow_mut().right_child_node = Some(Rc::clone(node));

    // Update the parent's child pointer
    if let Some(ref parent_weak) = left.borrow().parent_node {
        if let Some(parent) = parent_weak.upgrade() {
            if parent.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, node)) {
                parent.borrow_mut().left_child_node = Some(Rc::clone(&left));
            } else {
                parent.borrow_mut().right_child_node = Some(Rc::clone(&left));
            }
        }
    } else {
        tree.root_node = Some(Rc::clone(&left));
    }

    update_child_counts(node);
    update_depth(node);
    update_child_counts(&left);
    update_depth(&left);

    left
}

