    let right = node.borrow_mut().right_child_node.take().unwrap();
    let right_left = right.borrow_mut().left_child_node.take();

    let parent_weak = node.borrow().parent_node.clone();
    right.borrow_mut().parent_node = parent_weak;
    node.borrow_mut().parent_node = Some(Rc::downgrade(&right));

    if let Some(rl) = right_left {
        rl.borrow_mut().parent_node = Some(Rc::downgrade(node));
        node.borrow_mut().right_child_node = Some(rl);
    } else {
        node.borrow_mut().right_child_node = None;
    }

