#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

// Helper functions

fn imax(a: u32, b: u32) -> u32 {
    if a > b { a } else { b }
}

fn get_balance(node: &BOSNode) -> i32 {
    let left_depth = node.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    let right_depth = node.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    right_depth as i32 - left_depth as i32
}

fn total_count(child: &Option<Rc<RefCell<BOSNode>>>) -> u32 {
    match child {
        Some(n) => {
            let n = n.borrow();
            1 + n.left_child_count + n.right_child_count
        }
        None => 0,
    }
}

fn update_node_stats(node: &mut BOSNode) {
    node.left_child_count = total_count(&node.left_child_node);
    node.right_child_count = total_count(&node.right_child_node);
    let left_depth = node.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    let right_depth = node.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    node.depth = imax(left_depth, right_depth);
}

/// Rotate right around P. Returns the new root of the subtree (L).
fn rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Take L from P
    let l = {
        let mut p_mut = p.borrow_mut();
        p_mut.left_child_node.take().expect("rotate_right: no left child")
    };

    // Get L\'s current right child
    let lr = {
        let mut l_mut = l.borrow_mut();
        l_mut.right_child_node.take()
    };
    let lr_count = total_count(&lr);

    // Get P\'s parent
    let p_parent = {
        let mut p_mut = p.borrow_mut();
        p_mut.parent_node.take()
    };

    // Set P\'s left child to LR
    {
        let mut p_mut = p.borrow_mut();
        p_mut.left_child_node = lr.clone();
        p_mut.left_child_count = lr_count;
        if let Some(ref lr_node) = lr {
            lr_node.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }
    }

    // Set L\'s parent to P\'s old parent
    {
        let mut l_mut = l.borrow_mut();
        l_mut.parent_node = p_parent.clone();
    }

    // Update the parent\'s child pointer to L
    match p_parent {
        Some(ref parent_weak) => {
            if let Some(parent) = parent_weak.upgrade() {
                let mut parent_mut = parent.borrow_mut();
                if parent_mut.left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, p)) {
                    parent_mut.left_child_node = Some(l.clone());
                } else {
                    parent_mut.right_child_node = Some(l.clone());
                }
            }
        }
        None => {
            tree.root_node = Some(l.clone());
        }
    }

    // Link L to P
    {
        let mut l_mut = l.borrow_mut();
        l_mut.right_child_node = Some(p.clone());
    }
    {
        let mut p_mut = p.borrow_mut();
        p_mut.parent_node = Some(Rc::downgrade(&l));
    }

    // Update stats
    {
        let mut p_mut = p.borrow_mut();
        update_node_stats(&mut p_mut);
    }
    {
        let mut l_mut = l.borrow_mut();
        update_node_stats(&mut l_mut);
    }

    l
}

/// Rotate left around P. Returns the new root of the subtree (R).
fn rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Take R from P
    let r = {
        let mut p_mut = p.borrow_mut();
        p_mut.right_child_node.take().expect("rotate_left: no right child")
    };

    // Get R\'s current left child
    let rl = {
        let mut r_mut = r.borrow_mut();
        r_mut.left_child_node.take()
    };
    let rl_count = total_count(&rl);

    // Get P\'s parent
    let p_parent = {
        let mut p_mut = p.borrow_mut();
        p_mut.parent_node.take()
    };

    // Set P\'s right child to RL
    {
        let mut p_mut = p.borrow_mut();
        p_mut.right_child_node = rl.clone();
        p_mut.right_child_count = rl_count;
        if let Some(ref rl_node) = rl {
            rl_node.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }
    }

    // Set R\'s parent to P\'s old parent
    {
        let mut r_mut = r.borrow_mut();
        r_mut.parent_node = p_parent.clone();
    }

    // Update the parent\'s child pointer to R
    match p_parent {
        Some(ref parent_weak) => {
            if let Some(parent) = parent_weak.upgrade() {
                let mut parent_mut = parent.borrow_mut();
                if parent_mut.left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, p)) {
                    parent_mut.left_child_node = Some(r.clone());
                } else {
                    parent_mut.right_child_node = Some(r.clone());
                }
            }
        }
        None => {
            tree.root_node = Some(r.clone());
        }
    }

    // Link R to P
    {
        let mut r_mut = r.borrow_mut();
        r_mut.left_child_node = Some(p.clone());
    }
    {
        let mut p_mut = p.borrow_mut();
        p_mut.parent_node = Some(Rc::downgrade(&r));
    }

    // Update stats
    {
        let mut p_mut = p.borrow_mut();
        update_node_stats(&mut p_mut);
    }
    {
        let mut r_mut = r.borrow_mut();
        update_node_stats(&mut r_mut);
    }

    r
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        match &self.root_node {
            Some(root) => {
                let root = root.borrow();
                1 + root.left_child_count + root.right_child_count
            }
            None => 0,
        }
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        // Create new node
        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: None,
            key: key.clone(),
            data: data.clone(),
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        // If tree is empty, set as root
        if self.root_node.is_none() {
            self.root_node = Some(new_node.clone());
            return new_node;
        }

        // Traverse to find insertion point, incrementing child counts along the way
        let mut current = self.root_node.as_ref().unwrap().clone();
        loop {
            let cmp = {
                let current_borrow = current.borrow();
                (self.cmp_function)(&key, &current_borrow.key)
            };

            if cmp < 0 {
                // Go left
                let left_child = {
                    let mut current_mut = current.borrow_mut();
                    current_mut.left_child_count += 1;
                    current_mut.left_child_node.clone()
                };
                match left_child {
                    Some(child) => {
                        current = child;
                    }
                    None => {
                        // Insert as left child
                        let mut current_mut = current.borrow_mut();
                        current_mut.left_child_node = Some(new_node.clone());
                        new_node.borrow_mut().parent_node = Some(Rc::downgrade(&current));
                        break;
                    }
                }
            } else {
                // Go right (duplicates go right)
                let right_child = {
                    let mut current_mut = current.borrow_mut();
                    current_mut.right_child_count += 1;
                    current_mut.right_child_node.clone()
                };
                match right_child {
                    Some(child) => {
                        current = child;
                    }
                    None => {
                        // Insert as right child
                        let mut current_mut = current.borrow_mut();
                        current_mut.right_child_node = Some(new_node.clone());
                        new_node.borrow_mut().parent_node = Some(Rc::downgrade(&current));
                        break;
                    }
                }
            }
        }

        // Now rebalance from parent upwards
        // First, check if the parent previously had no other child (depth might have changed)
        let parent = {
            let new_borrow = new_node.borrow();
            new_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
        };

        if let Some(ref parent_rc) = parent {
            let has_both_children = {
                let parent_borrow = parent_rc.borrow();
                parent_borrow.left_child_node.is_some() && parent_borrow.right_child_node.is_some()
            };

            if !has_both_children {
                // Only one child before? Actually, we just added one, so if both existed before,
                // then depth didn\'t change. If only one existed (the new one), depth increased.
                // Actually: if the parent had 0 children before, now it has 1, depth increased.
                // If parent had 1 child before, now it has 2, depth didn\'t increase.
                // So depth increases iff before insertion the parent had 0 children.
                // We can check: before insertion, parent had 0 children if the other child is None.
                let had_zero_children = {
                    let parent_borrow = parent_rc.borrow();
                    parent_borrow.left_child_node.is_none() || parent_borrow.right_child_node.is_none()
                };
                // Actually, after insertion, one of left/right is the new node.
                // If the other is None, then before insertion there were 0 children.
                // But we need to check before we added... 
                // Since we just added one child, if the other child is None, then before insertion
                // there were 0 children, so depth increased.
            }
        }

        // Actually, let\'s rebalance from the new node up to root, similar to C code.
        // The C code first checks if parent depth changed (if it had 0 children before insertion),
        // then bubbles up updating depths and rebalancing.

        // Let me simplify: after insertion, walk up from the new node\'s parent to root,
        // updating depths and child counts, and rebalancing as needed.

        let mut bubble = parent.clone();
        while let Some(ref bubble_rc) = bubble {
            // Rebalance this node
            let balance = {
                let bubble_borrow = bubble_rc.borrow();
                get_balance(&bubble_borrow)
            };

            if balance < -1 {
                let left_balance = {
                    let bubble_borrow = bubble_rc.borrow();
                    bubble_borrow.left_child_node.as_ref().map_or(0, |n| get_balance(&n.borrow()))
                };
                if left_balance > 0 {
                    let left_child = {
                        let bubble_borrow = bubble_rc.borrow();
                        bubble_borrow.left_child_node.clone().unwrap()
                    };
                    rotate_left(self, &left_child);
                }
                let new_subtree = rotate_right(self, bubble_rc);
                bubble = {
                    let new_borrow = new_subtree.borrow();
                    new_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
                };
                continue;
            } else if balance > 1 {
                let right_balance = {
                    let bubble_borrow = bubble_rc.borrow();
                    bubble_borrow.right_child_node.as_ref().map_or(0, |n| get_balance(&n.borrow()))
                };
                if right_balance < 0 {
                    let right_child = {
                        let bubble_borrow = bubble_rc.borrow();
                        bubble_borrow.right_child_node.clone().unwrap()
                    };
                    rotate_right(self, &right_child);
                }
                let new_subtree = rotate_left(self, bubble_rc);
                bubble = {
                    let new_borrow = new_subtree.borrow();
                    new_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
                };
                continue;
            }

            // Update depth and check if it changed
            let old_depth = {
                let bubble_borrow = bubble_rc.borrow();
                bubble_borrow.depth
            };
            {
                let mut bubble_mut = bubble_rc.borrow_mut();
                update_node_stats(&mut bubble_mut);
            }
            let new_depth = {
                let bubble_borrow = bubble_rc.borrow();
                bubble_borrow.depth
            };

            if new_depth == old_depth {
                // Depth didn\'t change, but we still need to update child counts up the tree.
                // The child counts were already updated during traversal, so we can break.
                // Actually, child counts on this path were already incremented during insertion.
                // But the parent pointers may have changed due to rotations.
                // For non-rotated nodes, counts are already correct. For rotated nodes, 
                // update_node_stats fixed them.
                break;
            }

            // Move up
            bubble = {
                let bubble_borrow = bubble_rc.borrow();
                bubble_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
            };
        }

        new_node
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        // If node has two children, find successor (leftmost in right subtree)
        let node_to_remove = {
            let node_borrow = node.borrow();
            if node_borrow.left_child_node.is_some() && node_borrow.right_child_node.is_some() {
                // Find successor
                let mut successor = node_borrow.right_child_node.clone().unwrap();
                loop {
                    let next = {
                        let succ_borrow = successor.borrow();
                        succ_borrow.left_child_node.clone()
                    };
                    match next {
                        Some(n) => successor = n,
                        None => break,
                    }
                }
                // Swap key and data between node and successor
                drop(node_borrow);
                {
                    let mut node_mut = node.borrow_mut();
                    let mut succ_mut = successor.borrow_mut();
                    std::mem::swap(&mut node_mut.key, &mut succ_mut.key);
                    std::mem::swap(&mut node_mut.data, &mut succ_mut.data);
                }
                // Now remove successor (which has at most one child)
                successor
            } else {
                // Node has at most one child, remove it directly
                node.clone()
            }
        };

        // Now node_to_remove has at most one child
        let (child, child_count) = {
            let ntr_borrow = node_to_remove.borrow();
            if let Some(ref left) = ntr_borrow.left_child_node {
                (Some(left.clone()), ntr_borrow.left_child_count)
            } else if let Some(ref right) = ntr_borrow.right_child_node {
                (Some(right.clone()), ntr_borrow.right_child_count)
            } else {
                (None, 0)
            }
        };

        // Get parent of node_to_remove
        let parent = {
            let ntr_borrow = node_to_remove.borrow();
            ntr_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
        };

        // Replace node_to_remove with its child
        match &parent {
            Some(parent_rc) => {
                let mut parent_mut = parent_rc.borrow_mut();
                if parent_mut.left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &node_to_remove)) {
                    parent_mut.left_child_node = child.clone();
                    parent_mut.left_child_count = child_count;
                } else {
                    parent_mut.right_child_node = child.clone();
                    parent_mut.right_child_count = child_count;
                }
            }
            None => {
                // Removing root
                self.root_node = child.clone();
            }
        }

        if let Some(ref child_rc) = child {
            child_rc.borrow_mut().parent_node = parent.as_ref().map(|p| Rc::downgrade(p));
        }

        // Mark node as invalid
        node_to_remove.borrow_mut().weak_ref_node_valid = 0;

        // Rebalance from parent up
        let mut bubble = parent.clone();
        let mut bubbling_finished = false;
        while let Some(ref bubble_rc) = bubble {
            // Update depth and check balance if not finished bubbling
            if !bubbling_finished {
                let old_depth = {
                    let bubble_borrow = bubble_rc.borrow();
                    bubble_borrow.depth
                };

                // Rebalance
                let balance = {
                    let bubble_borrow = bubble_rc.borrow();
                    get_balance(&bubble_borrow)
                };

                if balance < -1 {
                    let left_balance = {
                        let bubble_borrow = bubble_rc.borrow();
                        bubble_borrow.left_child_node.as_ref().map_or(0, |n| get_balance(&n.borrow()))
                    };
                    if left_balance > 0 {
                        let left_child = {
                            let bubble_borrow = bubble_rc.borrow();
                            bubble_borrow.left_child_node.clone().unwrap()
                        };
                        rotate_left(self, &left_child);
                    }
                    let new_subtree = rotate_right(self, bubble_rc);
                    bubble = {
                        let new_borrow = new_subtree.borrow();
                        new_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
                    };
                    continue;
                } else if balance > 1 {
                    let right_balance = {
                        let bubble_borrow = bubble_rc.borrow();
                        bubble_borrow.right_child_node.as_ref().map_or(0, |n| get_balance(&n.borrow()))
                    };
                    if right_balance < 0 {
                        let right_child = {
                            let bubble_borrow = bubble_rc.borrow();
                            bubble_borrow.right_child_node.clone().unwrap()
                        };
                        rotate_right(self, &right_child);
                    }
                    let new_subtree = rotate_left(self, bubble_rc);
                    bubble = {
                        let new_borrow = new_subtree.borrow();
                        new_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
                    };
                    continue;
                } else {
                    let mut bubble_mut = bubble_rc.borrow_mut();
                    update_node_stats(&mut bubble_mut);
                    let new_depth = bubble_mut.depth;
                    if new_depth == old_depth {
                        bubbling_finished = true;
                    }
                }
            }

            // Update child counts up the tree
            // The parent\'s child count should have been updated when we replaced the node.
            // But we still need to decrement counts of further ancestors.
            // Actually, the child counts of ancestors of the removed node need to be decremented.
            // Since we replaced the node with its child (which has fewer total nodes),
            // the counts of all ancestors need to be updated.

            // The parent\'s count was already fixed. Now move up.
            let next_bubble = {
                let bubble_borrow = bubble_rc.borrow();
                bubble_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
            };

            if let Some(ref next_rc) = next_bubble {
                let mut next_mut = next_rc.borrow_mut();
                if next_mut.left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, bubble_rc)) {
                    next_mut.left_child_count = total_count(&next_mut.left_child_node);
                } else {
                    next_mut.right_child_count = total_count(&next_mut.right_child_node);
                }
            }

            bubble = next_bubble;
        }

        // Call bostree_node_weak_unref on the removed node
        self.bostree_node_weak_unref(&node_to_remove);
    }

    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let mut node_mut = node.borrow_mut();
        node_mut.weak_ref_count -= 1;
        if node_mut.weak_ref_count == 0 {
            if let Some(ref free_fn) = self.free_function {
                free_fn(node);
            }
            None
        } else if node_mut.weak_ref_node_valid != 0 {
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(node) = current {
            let cmp = {
                let node_borrow = node.borrow();
                (self.cmp_function)(key, &node_borrow.key)
            };
            if cmp == 0 {
                return Some(node);
            } else if cmp < 0 {
                let next = {
                    let node_borrow = node.borrow();
                    node_borrow.left_child_node.clone()
                };
                current = next;
            } else {
                let next = {
                    let node_borrow = node.borrow();
                    node_borrow.right_child_node.clone()
                };
                current = next;
            }
        }
        None
    }

    pub fn bostree_select(&self, mut index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(node) = current {
            let left_count = {
                let node_borrow = node.borrow();
                node_borrow.left_child_count
            };
            if left_count <= index {
                index -= left_count;
                if index == 0 {
                    return Some(node);
                }
                index -= 1;
                let next = {
                    let node_borrow = node.borrow();
                    node_borrow.right_child_node.clone()
                };
                current = next;
            } else {
                let next = {
                    let node_borrow = node.borrow();
                    node_borrow.left_child_node.clone()
                };
                current = next;
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        fn print_helper(node: &Rc<RefCell<BOSNode>>) {
            let node_borrow = node.borrow();
            println!(
                "  {} [label=\\"\\N ({},{},{})\\"];",
                node_borrow.key,
                node_borrow.left_child_count,
                node_borrow.right_child_count,
                node_borrow.depth
            );
            if let Some(ref parent_weak) = node_borrow.parent_node {
                if let Some(parent) = parent_weak.upgrade() {
                    println!(
                        "  {} -> {} [color=green];",
                        node_borrow.key,
                        parent.borrow().key
                    );
                }
            }
            if let Some(ref left) = node_borrow.left_child_node {
                println!("  {} -> {}", node_borrow.key, left.borrow().key);
                print_helper(left);
            }
            if let Some(ref right) = node_borrow.right_child_node {
                println!("  {} -> {}", node_borrow.key, right.borrow().key);
                print_helper(right);
            }
        }

        if let Some(ref root) = self.root_node {
            println!("digraph {{\n  ordering = out;");
            print_helper(root);
            println!("}}");
        }
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>>) -> Rc<RefCell<BOSNode>> {
    let mut node_mut = node.borrow_mut();
    assert!(node_mut.weak_ref_count < 127);
    assert!(node_mut.weak_ref_count > 0);
    node_mut.weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>>) -> Option<Rc<RefCell<BOSNode>>> {
    let node_borrow = node.borrow();
    if let Some(ref right) = node_borrow.right_child_node {
        let mut current = right.clone();
        loop {
            let next = {
                let cur_borrow = current.borrow();
                cur_borrow.left_child_node.clone()
            };
            match next {
                Some(n) => current = n,
                None => return Some(current),
            }
        }
    }
    // Go up while we are the right child
    let mut current = node_borrow.parent_node.as_ref().and_then(|w| w.upgrade());
    let mut prev = node.clone();
    while let Some(ref cur) = current {
        let is_right_child = {
            let cur_borrow = cur.borrow();
            cur_borrow.right_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &prev))
        };
        if !is_right_child {
            return Some(cur.clone());
        }
        prev = cur.clone();
        let next = {
            let cur_borrow = cur.borrow();
            cur_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
        };
        current = next;
    }
    None
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>>) -> Option<Rc<RefCell<BOSNode>>> {
    let node_borrow = node.borrow();
    if let Some(ref left) = node_borrow.left_child_node {
        let mut current = left.clone();
        loop {
            let next = {
                let cur_borrow = current.borrow();
                cur_borrow.right_child_node.clone()
            };
            match next {
                Some(n) => current = n,
                None => return Some(current),
            }
        }
    }
    // Go up while we are the left child
    let mut current = node_borrow.parent_node.as_ref().and_then(|w| w.upgrade());
    let mut prev = node.clone();
    while let Some(ref cur) = current {
        let is_left_child = {
            let cur_borrow = cur.borrow();
            cur_borrow.left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &prev))
        };
        if !is_left_child {
            return Some(cur.clone());
        }
        prev = cur.clone();
        let next = {
            let cur_borrow = cur.borrow();
            cur_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
        };
        current = next;
    }
    None
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>>) -> u32 {
    let node_borrow = node.borrow();
    let mut counter = node_borrow.left_child_count;
    let mut current = node_borrow.parent_node.as_ref().and_then(|w| w.upgrade());
    let mut prev = node.clone();
    while let Some(ref cur) = current {
        let is_right_child = {
            let cur_borrow = cur.borrow();
            cur_borrow.right_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &prev))
        };
        if is_right_child {
            let left_count = {
                let cur_borrow = cur.borrow();
                cur_borrow.left_child_count
            };
            counter += 1 + left_count;
        }
        prev = cur.clone();
        let next = {
            let cur_borrow = cur.borrow();
            cur_borrow.parent_node.as_ref().and_then(|w| w.upgrade())
        };
        current = next;
    }
    counter
}
